---@class CommonGoodsList
---@field GoodNode                      	UnityEngine.RectTransform
local CommonGoodsList = Class("CommonGoodsList")
function CommonGoodsList:__init()
    self.data = {}
    self.goodNodeList = {}

end

function CommonGoodsList:__delete()
    self.controller = nil
    self.data = {}
    self.goodNodeList = {}

end


---@param data table rewards
---@param canGet boolean 可领取特效
---@param isGet boolean 已领取蒙版
---@param isShowNum boolean 显示奖励数量，不传默认显示
---@param isCheckNum boolean 是否检查道具数量
---@param isShowGoodsNumTips boolean 是否显示道具提示中的拥有数量
function CommonGoodsList:FreshBaseUI(data, canGet, isGet, isShowNum, isCheckNum, isShowGoodsTips, isShowGoodsNumTips)
    if isNull(data) then
        return
    end
    if isNull(isShowNum) then--不传默认显示
        isShowNum = true
    end
    self.data = data
    local goCount = self.controller.transform.childCount - 1 --减去默认prefab的数量
    if goCount > #data then
        for i = #data + 1, goCount do --复用时隐藏多出来的
            KTool.SetActive(self.goodNodeList[i], false)
        end
    end
    for i = 1, #data do
        local go
        go = self.goodNodeList[i]
        if not go then
            go = CfUtils.InstantiateGo(self.GoodNode, self.controller.gameObject)
            go.name = "GoodNode"..i
            self.goodNodeList[i] = go.gameObject
        end
        ---@type GoodNodeMB
        local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
        local goodsId = data[i].goodsId or data[i].id
        local num = data[i].goodsNum or data[i].num
        local type = checkNumber(data[i].type)
        local _isGet = checkBool(data[i].isGet)

        goEnv:SetSanXingGainShow(_isGet)
        --@region 底部title 需要额外添加才会显示
        if not isNull(data[i].bottomTitle) then
            local txtBottom = go.transform:Find("Remain/TextDesc")
            if txtBottom then
                CfUtils.FillText(txtBottom, data[i].bottomTitle)
            end
        end
        --@endregion
        goEnv:SetClickButtonAction(function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if isTable(vo) then
                if not canGet then
                    if isShowGoodsTips then
                        GameUtils.ShowCommonGoodsTipsBoard(go, goodsId, true)
                    else
                        GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id, isShowGoodsNumTips)
                    end
                end
            end
        end)
        KTool.SetActive(go, true)
        goEnv:Reload(
                {
                    goodsId = goodsId,
                    isShowNo = isShowNum, text = self:GetText(isShowNum, num, goodsId, isCheckNum),
                    superScript = type
                }
        )
        if not isNull(canGet) then
            goEnv:SetCanGetEffectShow(canGet)
        end
        if not isNull(isGet) then
            goEnv:SetSanXingGainShow(isGet)
        end
        
    end
end

function CommonGoodsList:GetText(isShowNum, num, goodsId, isCheckNum)
    if not isShowNum then
        return nil
    end
    if isCheckNum then
        return GoodsUtils.GetGoodsText(goodsId, num, 1) --- GoodsUtils.GetConsumeGoodsText(goodsId, num)
    end
    if GameUtils.isZmFunction() then
        return 'x ' .. FormatCurrencyNum(num)
    else
        return 'x' .. FormatCurrencyNum(num)
    end
end

---可领取特效的显示与否
function CommonGoodsList:SetCanGetEffectShow(canGet)
    for i = 1, #self.data do
        local go
        go = self.goodNodeList[i]
        if go then
            local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            if goEnv then
                goEnv:SetCanGetEffectShow(canGet)
            end
        end
    end
end

---已领取蒙版的显示与否
function CommonGoodsList:SetIsGetMaskShow(isGet)
    for i = 1, #self.data do
        local go
        go = self.goodNodeList[i]
        if go then
            local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            if goEnv then
                goEnv:SetSanXingGainShow(isGet)
            end
        end
    end
end

---已领取蒙版的显示与否
function CommonGoodsList:SetCountDownShow(showTxtFun)
    for i = 1, #self.data do
        local go
        go = self.goodNodeList[i]
        if go then
            local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            if goEnv then
                local isShow = self.data[i].isLimit and self.data[i].duration > 0
                local showTxt = isShow and showTxtFun(self.data[i].duration) or ""
                goEnv:SetCountDownShow(isShow,showTxt)
            end
        end
    end
end

function CommonGoodsList:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return CommonGoodsList